password = "Lahore2025"
min_length = 8

has_letter = False
has_digit = False
for ch in password:
    if ch.isalpha():
        has_letter = True
    if ch.isdigit():
        has_digit = True

print("Length:", len(password))
if len(password) >= min_length and has_letter and has_digit:
    print("Strong alpha-numeric password")
else:
    print("Weak: use at least", min_length, "letters and numbers")
